def bfs_order(adj, src):
    seen = {src}
    queue = [src]
    out = []
    while queue:
        u = queue.pop(0)
        out.append(u)
        for v in adj[u]:
            if v not in seen:
                seen.add(v)
                queue.append(v)
    return out
